// ===================== FLASHCARD DATA =====================
const fcData=[{"w":"La regla de oro, aplicada a la escena","a":"🎭 Ninguna pieza de esta etapa se cita sin autor y año. La escena como unidad de trabajo es de Robert McKee, «Story» (1997); el objetivo y el subtexto, de Konstantin Stanislavski (1936); el corte, de David Mamet (1991). Cada herramienta con su fecha de fabricación."},{"w":"La escena como unidad de trabajo","a":"🎬 Robert McKee, «Story» (1997): la escena, no la línea ni el acto, es la unidad mínima de trabajo de un relato. Cada escena debe hacer una sola cosa: girar una carga de valor de positivo a negativo o de negativo a positivo."},{"w":"El giro de valor","a":"⚖️ McKee (1997): toda escena arranca en un valor (poder, verdad, vida, confianza) con un signo, y termina con el signo cambiado. Si el signo con el que se entra es el mismo con el que se sale, no pasó nada de verdad."},{"w":"El no-acontecimiento","a":"🚫 McKee (1997) llama «no-acontecimiento» a la escena donde nada cambia: alguien entra queriendo algo, lo consigue o no sin sorpresa, y la escena podría borrarse sin que la historia se entere. Es la escena más común de un primer borrador."},{"w":"El beat","a":"🔹 McKee (1997): dentro de una escena, un beat es un intercambio de acción y reacción (lo que alguien hace y lo que el otro hace a cambio). Varios beats encadenados son los que empujan el valor de un signo al otro."},{"w":"El objetivo (Stanislavski)","a":"🎯 Konstantin Stanislavski, «El trabajo del actor sobre sí mismo» (1936): cada personaje entra a la escena queriendo algo concreto y activo, su objetivo. Sin un objetivo que se pueda perseguir, el actor no tiene qué hacer, y la escena no tiene motor."},{"w":"El si mágico","a":"🪄 Stanislavski (1936): el actor se pregunta «¿qué haría YO si esto me estuviera pasando de verdad?». El si mágico convierte una circunstancia inventada en un impulso real de actuar, en vez de una emoción fingida desde fuera."},{"w":"El subtexto","a":"🗣️ Del sistema de Stanislavski (1936): lo que un personaje dice casi nunca es lo que de verdad quiere. El subtexto es la corriente de deseo que corre debajo del diálogo, y es lo que un actor (o un escritor) tiene que actuar de verdad."},{"w":"Entrar tarde, salir temprano","a":"✂️ David Mamet, «On Directing Film» (1991): la escena no empieza cuando alguien llega ni termina cuando se va. Empieza en el último momento posible antes de que algo tenga que decidirse, y termina en el primero después de que ya se decidió."},{"w":"La escena que explica","a":"🙅 Mamet (1991) ataca la escena donde los personajes se sientan a contarse lo que el público ya sabe, o lo que el guionista no supo mostrar de otro modo. Una escena así no gira ningún valor: solo informa, y se puede cortar entera."},{"w":"La escena francesa","a":"🎭 Convención de la dramaturgia clásica (sin autor único): en el texto impreso, una escena nueva empieza cada vez que un personaje entra o sale del escenario. Sirve para contar el pulso real de una obra, entrada por entrada."},{"w":"El plano secuencia y la profundidad de campo","a":"🎥 André Bazin, «¿Qué es el cine?» (1958-1962): defiende el plano secuencia y la profundidad de campo frente al montaje. Una escena puede girar su valor sin un solo corte, si dentro del plano hay espacio para que el ojo elija qué mirar."},{"w":"Las memorias de oficio","a":"✍️ William Goldman, «Adventures in the Screen Trade» (1983): memorias de un guionista de Hollywood sobre cómo se vende, se filma y se destroza una historia en el camino. Anécdota de oficio, no un método que se pueda aplicar paso a paso."},{"w":"Nadie sabe nada, bien citado","a":"🎲 La frase de Goldman (1983) es sobre el NEGOCIO: nadie puede predecir qué película va a triunfar en taquilla. No es una excusa para no trabajar una escena: cómo se escribe una escena sí se puede aprender y comprobar."},{"w":"La cuenta de la escena","a":"🧮 La herramienta de esta etapa, para usar en cualquier escena real: valor al entrar, valor al salir, y qué lo movió (el beat o los beats concretos). Si las tres casillas no se pueden llenar, probablemente no hay escena todavía."},{"w":"El caso de La Gaviota","a":"🕊️ Chéjov estrenó «La Gaviota» en 1896 en el Alexandrinski de San Petersburgo: fue un fracaso tan estrepitoso que juró no volver a escribir teatro. En 1898 el Teatro de Arte de Moscú, con Stanislavski, la repuso y fue un triunfo: la gaviota es hoy el emblema de ese teatro."}];
let fcIdx=0;
function upFC(){document.getElementById('fcInner').classList.remove('flipped');document.getElementById('fcW').textContent=fcData[fcIdx].w;document.getElementById('fcA').innerHTML=fcData[fcIdx].a;document.getElementById('fcCtr').textContent=(fcIdx+1)+' / '+fcData.length;}
function flipCard(){sfx('flip');document.getElementById('fcInner').classList.toggle('flipped');if(!xpTracker.fc.has(fcIdx)){xpTracker.fc.add(fcIdx);pts(1);}if(xpTracker.fc.size===fcData.length){fin('s-flash');unlockAchievement('flash_master');}}
function nextFC(){sfx('click');fcIdx=(fcIdx+1)%fcData.length;upFC();}
function prevFC(){sfx('click');fcIdx=(fcIdx-1+fcData.length)%fcData.length;upFC();}

