const qzData=[{"q":"Según Robert McKee («Story», 1997), ¿qué es lo que de verdad hace que un trozo de guion sea una escena?","o":["a) Que tenga diálogo entre dos personajes","b) Que dure más de un minuto","c) Que ocurra en un solo lugar","d) Que gire una carga de valor de un signo al signo contrario"],"c":3,"e":"McKee (1997) define la escena por su efecto, no por su forma: tiene que cambiar el valor con el que se entró (de + a - o de - a +). Sin ese giro, es un no-acontecimiento."},{"q":"¿Cómo llama McKee (1997) a la escena donde nada cambia de signo?","o":["a) Beat muerto","b) No-acontecimiento","c) Escena francesa","d) Plano secuencia"],"c":1,"e":"El no-acontecimiento es la escena que podría borrarse del guion sin que la historia se entere, porque nadie sale distinto de como entró."},{"q":"Según Stanislavski («El trabajo del actor sobre sí mismo», 1936), ¿qué necesita un personaje para que la escena tenga motor?","o":["a) Un monólogo largo","b) Un narrador que explique sus intenciones","c) Una acotación con la emoción escrita","d) Un objetivo concreto y activo, no un sentimiento suelto"],"c":3,"e":"Stanislavski (1936) insiste en el objetivo: qué quiere conseguir el personaje AHORA, en esta escena. Sin objetivo que perseguir, el actor no tiene qué actuar."},{"q":"¿Qué es el subtexto, en el sistema de Stanislavski (1936)?","o":["a) Las acotaciones del autor","b) La corriente de deseo que corre debajo de lo que se dice en voz alta","c) El resumen de la escena anterior","d) La música de fondo de la escena"],"c":1,"e":"Lo que un personaje dice casi nunca es lo que de verdad quiere; el subtexto es ese deseo de fondo, y es lo que hay que actuar (o escribir) de verdad."},{"q":"¿Qué significa «entrar tarde, salir temprano», la máxima de David Mamet («On Directing Film», 1991)?","o":["a) Empezar la escena en el último momento posible y cortarla en el primero posible después de decidido lo importante","b) Llegar impuntual al rodaje","c) Filmar solo escenas cortas","d) Grabar siempre de noche"],"c":0,"e":"Mamet (1991) pide cortar todo lo prescindible: nada de saludos ni despedidas si la escena no gira en torno a ellos. El corte es una herramienta, no un ahorro."},{"q":"¿Qué defiende André Bazin en «¿Qué es el cine?» (1958-1962), frente al montaje?","o":["a) Los quince golpes de una plantilla comercial","b) El objetivo y el subtexto del actor","c) El plano secuencia y la profundidad de campo","d) La escena francesa"],"c":2,"e":"Bazin defiende que una escena puede significar sin cortarse: con profundidad de campo, el espectador elige dónde mirar dentro del mismo plano, en vez de que el montaje se lo imponga."},{"q":"¿Sobre qué es en realidad la frase «nadie sabe nada» de William Goldman («Adventures in the Screen Trade», 1983)?","o":["a) Sobre que nadie puede predecir qué película va a triunfar en taquilla","b) Sobre cómo se estructura una escena","c) Sobre que los actores no saben actuar","d) Sobre que el cine no tiene reglas de ningún tipo"],"c":0,"e":"Goldman habla del negocio: nadie puede predecir un éxito de taquilla. No es una excusa para no trabajar una escena con método; eso sí se puede aprender y comprobar."},{"q":"¿Qué es «la escena francesa», y quién la propuso?","o":["a) Robert McKee, en 1997","b) Una convención de la dramaturgia clásica, sin autor único, marcada por entradas y salidas de personajes","c) David Mamet, en 1991","d) Un hallazgo medido con un corpus de obras"],"c":1,"e":"Es un término tradicional de análisis teatral: en el texto impreso, entra una nueva escena cada vez que un personaje entra o sale del escenario. Se declara sin autor único."},{"q":"Según la «cuenta de la escena» de esta etapa, ¿qué tres cosas hay que poder escribir de cualquier escena real?","o":["a) El título, la fecha y el lugar","b) El presupuesto, el elenco y la locación","c) El valor al entrar, el valor al salir, y qué lo movió","d) El género, el tono y la duración"],"c":2,"e":"La cuenta de la escena es la herramienta práctica de esta etapa: valor al entrar, valor al salir, y qué acción o revelación concreta (el beat) movió lo uno a lo otro."},{"q":"¿Qué le pasó a «La Gaviota» de Chéjov entre 1896 y 1898?","o":["a) Fracasó en 1896 y triunfó en 1898 con el Teatro de Arte de Moscú y Stanislavski","b) Se estrenó dos veces con el mismo éxito","c) Nunca se representó","d) Ganó un premio en su primer estreno"],"c":0,"e":"El estreno de 1896 en San Petersburgo fue un fracaso; la reposición de 1898 en el Teatro de Arte de Moscú, dirigida con el método naciente de Stanislavski, fue un triunfo: la gaviota es hoy el emblema de ese teatro."}];
let qzIdx=0,qzSel=-1,qzDone=false;
function buildQz(){qzIdx=0;qzSel=-1;qzDone=false;showQz();}
