const identifyTaskDB=[{"s":"Unidad mínima de trabajo de un relato: gira una carga de valor de un signo al contrario.","type":"La escena (McKee, 1997)"},{"s":"Lo que un personaje persigue de forma concreta y activa dentro de una escena.","type":"El objetivo (Stanislavski, 1936)"},{"s":"La corriente de deseo que corre debajo de lo que un personaje dice en voz alta.","type":"El subtexto (Stanislavski, 1936)"},{"s":"Empezar la escena en el último momento posible y cortarla en el primero después de lo decidido.","type":"Entrar tarde, salir temprano (Mamet, 1991)"},{"s":"Defensa del plano secuencia y la profundidad de campo frente al montaje.","type":"André Bazin (1958-1962)"},{"s":"Unidad teatral marcada por la entrada o salida de un personaje, sin autor único.","type":"La escena francesa"},{"s":"Memorias de un guionista sobre cómo se vende y se filma una historia en Hollywood.","type":"William Goldman (1983)"},{"s":"La escena donde nada cambia de signo, y que podría borrarse sin que la historia se entere.","type":"El no-acontecimiento (McKee, 1997)"},{"s":"El intercambio mínimo de acción y reacción dentro de una escena.","type":"El beat (McKee, 1997)"},{"s":"La pregunta que el actor se hace para actuar un impulso real en vez de una emoción fingida.","type":"El si mágico (Stanislavski, 1936)"}];
const classifyTaskDB=[{"w":"El giro de valor","gen":"Herramienta","n":"Cambio de signo entre la entrada y la salida","g":"Manual de oficio","t":"McKee, 1997"},{"w":"El objetivo","gen":"Herramienta","n":"Lo que persigue el personaje en la escena","g":"Sistema de actor","t":"Stanislavski, 1936"},{"w":"El subtexto","gen":"Herramienta","n":"Lo que se quiere, debajo de lo que se dice","g":"Sistema de actor","t":"Stanislavski, 1936"},{"w":"Entrar tarde, salir temprano","gen":"Postura de oficio","n":"El corte como herramienta de significado","g":"Dirección de cine","t":"Mamet, 1991"},{"w":"El plano secuencia","gen":"Tesis crítica","n":"Defiende la profundidad de campo frente al montaje","g":"Teoría de cine","t":"Bazin, 1958-1962"},{"w":"La escena francesa","gen":"Término tradicional","n":"Marcada por entradas y salidas de personajes","g":"Dramaturgia clásica","t":"Sin autor único"},{"w":"Nadie sabe nada","gen":"Anécdota de oficio","n":"Sobre la taquilla, no sobre cómo se escribe","g":"Memorias de Hollywood","t":"Goldman, 1983"},{"w":"El no-acontecimiento","gen":"Diagnóstico","n":"La escena donde nada cambió de signo","g":"Manual de oficio","t":"McKee, 1997"},{"w":"El beat","gen":"Unidad menor","n":"Un intercambio de acción y reacción","g":"Manual de oficio","t":"McKee, 1997"},{"w":"El si mágico","gen":"Herramienta","n":"«¿Qué haría yo si esto me pasara de verdad?»","g":"Sistema de actor","t":"Stanislavski, 1936"}];
const completeTaskDB=[{"s":"La escena, según McKee, gira una carga de ___.","opts":["personajes","valor","escenografía"],"ans":"valor"},{"s":"Stanislavski publicó su sistema del objetivo en ___.","opts":["1936","1979","2005"],"ans":"1936"},{"s":"El ___ es lo que un personaje quiere de verdad, debajo del diálogo.","opts":["subtexto","presupuesto","vestuario"],"ans":"subtexto"},{"s":"David Mamet pide entrar tarde y salir ___.","opts":["temprano","despacio","llorando"],"ans":"temprano"},{"s":"Bazin defendió la profundidad de campo frente al ___.","opts":["diálogo","montaje","vestuario"],"ans":"montaje"},{"s":"La escena ___ se marca por entradas y salidas de personajes.","opts":["francesa","rusa","muda"],"ans":"francesa"},{"s":"«Nadie sabe nada» de Goldman es sobre el ___ del cine.","opts":["negocio","guion","subtexto"],"ans":"negocio"},{"s":"Si el valor no cambia de signo, McKee lo llama un ___.","opts":["clímax","no-acontecimiento","giro"],"ans":"no-acontecimiento"}];
const explainQuestions=[{"q":"Explica qué es el giro de valor de McKee (1997) y por qué una escena sin ese giro se llama «no-acontecimiento».","ans":"El giro de valor es la idea central de Robert McKee en «Story» (1997): toda escena arranca en un valor de la vida (poder, verdad, confianza, vida) con un signo, positivo o negativo, y para que de verdad sea una escena tiene que terminar con ese signo cambiado. Si un personaje entra queriendo algo y sale con exactamente lo mismo que tenía al entrar, sin que nada haya cambiado para él ni para quien lo mira, McKee llama a eso un «no-acontecimiento»: una escena que se puede borrar del guion entero sin que la historia se entere, porque no movió nada. La prueba práctica es simple: si no se puede escribir en una frase qué cambió entre el principio y el final, probablemente no había escena, había solo información puesta en boca de dos personajes."},{"q":"Explica la diferencia entre el objetivo de un personaje y el subtexto, según el sistema de Stanislavski (1936).","ans":"Konstantin Stanislavski, en «El trabajo del actor sobre sí mismo» (1936), distingue dos capas de la misma escena. El objetivo es lo que un personaje quiere conseguir de forma concreta y activa AHORA, en esta escena: convencer, sonsacar, disculparse, ganar tiempo. El subtexto, en cambio, es la corriente de deseo que corre por debajo de lo que ese personaje dice en voz alta, porque casi nunca se dice de frente lo que de verdad se quiere. Un personaje puede tener el objetivo de que le perdonen una deuda y decir, en la superficie, que solo pasaba a saludar: el objetivo mueve la escena, y el subtexto es lo que el actor (o quien escribe) tiene que sostener por dentro mientras las palabras de la superficie dicen otra cosa."},{"q":"Explica qué significa «entrar tarde, salir temprano» (Mamet, 1991) y qué gana una escena al aplicarlo.","ans":"David Mamet, en «On Directing Film» (1991), defiende que una escena no debería empezar cuando un personaje llega a un lugar ni terminar cuando se va: debería empezar en el último momento posible antes de que algo tenga que decidirse, y terminar en el primero posible después de que ya se decidió. Aplicado en serio, esto obliga a cortar los saludos, las explicaciones de contexto y las despedidas que no cambian ningún valor, y deja solo el tramo de la escena donde de verdad hay un giro. Lo que se gana es ritmo y honestidad: el público no tiene que sentarse a ver cómo alguien llega y cuelga el abrigo si eso no mueve nada, y la escena que queda es, casi siempre, más corta y más tensa que el primer borrador."},{"q":"Explica en qué consiste la disputa entre Mamet (1991) y Bazin (1958-1962) sobre cómo se talla una escena.","ans":"La disputa que esta etapa presenta en su careo enfrenta a David Mamet (1991), que defiende cortar (entrar tarde, salir temprano, y dejar que el montaje decida qué ve el público en cada instante), con André Bazin, que en «¿Qué es el cine?» (1958-1962) defendió el plano secuencia y la profundidad de campo frente al montaje: para Bazin, un plano largo y bien compuesto permite que el espectador elija con libertad dónde mirar dentro de la misma imagen, sin que un corte le imponga la lectura. Las dos posturas quieren lo mismo, que la escena signifique y gire en un valor; lo que discuten es dónde va el corte y qué se pierde exactamente cuando se corta: para Mamet se gana ritmo, para Bazin se pierde la ambigüedad y la libertad de mirada que solo da el tiempo real sin interrumpir."},{"q":"Explica por qué la frase «nadie sabe nada» de Goldman (1983) no sirve como excusa para no trabajar una escena.","ans":"William Goldman escribió «nadie sabe nada» en «Adventures in the Screen Trade» (1983), pero lo escribió hablando del negocio del cine: nadie, ni los estudios más grandes, puede predecir con certeza qué película va a triunfar en la taquilla. Es una frase sobre la impredecibilidad del éxito comercial, no sobre si se puede aprender a escribir bien una escena. Confundir las dos cosas es exactamente el error que esta etapa enseña a no cometer: cómo se construye el giro de valor, el objetivo de un personaje o el corte de una escena sí se puede estudiar, practicar y comprobar, aunque nadie pueda garantizar después cuánta gente vaya a pagar por verla."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra la herramienta ilustrada en cada oración. Escribe al lado de qué herramienta se trata.','<strong>Ejemplo:</strong> La corriente de deseo que corre debajo de lo que un personaje dice en voz alta. → <span style="color:var(--jade);font-weight:700;">El subtexto (Stanislavski, 1936)</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y nota.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Nota')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Nota: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
