const evalTFBank=[{"q":"La regla de oro de esta materia exige que toda pieza de la escena se cite con autor y año.","a":true},{"q":"McKee (1997) llama «no-acontecimiento» a la escena donde el valor cambia de signo.","a":false},{"q":"Stanislavski (1936) sostiene que el objetivo del personaje es lo que produce el impulso de actuar, no al revés.","a":true},{"q":"El subtexto es lo mismo que las acotaciones que el autor escribe entre paréntesis.","a":false},{"q":"Mamet (1991) defiende entrar tarde y salir temprano de una escena.","a":true},{"q":"Bazin defendió el montaje por encima del plano secuencia.","a":false},{"q":"«Nadie sabe nada», de Goldman (1983), es una frase sobre cómo se escribe una escena.","a":false},{"q":"La escena francesa se marca por la entrada o salida de un personaje.","a":true},{"q":"El «si mágico» de Stanislavski es la pregunta «¿qué haría yo si esto me pasara de verdad?».","a":true},{"q":"Un beat, para McKee, es un intercambio de acción y reacción dentro de la escena.","a":true},{"q":"La cuenta de la escena de esta etapa se compone de valor al entrar, valor al salir y qué lo movió.","a":true},{"q":"«La Gaviota» de Chéjov triunfó en su primer estreno de 1896.","a":false},{"q":"Bazin escribió «¿Qué es el cine?», publicado entre 1958 y 1962.","a":true},{"q":"El corte de Mamet y el plano secuencia de Bazin dicen exactamente lo mismo con otras palabras.","a":false},{"q":"La escena francesa tiene un autor único al que se le puede poner una fecha exacta.","a":false}];
const evalMCBank=[{"q":"¿Qué es lo que de verdad convierte un trozo de guion en una escena, según McKee (1997)?","o":["a) Que tenga diálogo","b) Que dure un minuto o más","c) Que gire una carga de valor de un signo al contrario","d) Que pase en un solo lugar"],"a":2},{"q":"¿Cómo se llama la escena donde nada cambia de signo?","o":["a) El beat","b) La escena francesa","c) El plano secuencia","d) El no-acontecimiento"],"a":3},{"q":"¿Qué necesita un personaje para que la escena tenga motor, según Stanislavski (1936)?","o":["a) Un objetivo concreto y activo","b) Un monólogo","c) Una acotación con la emoción escrita","d) Un narrador"],"a":0},{"q":"¿Qué es el subtexto?","o":["a) El resumen del acto anterior","b) La corriente de deseo debajo de lo que se dice","c) La música de la escena","d) Las acotaciones del autor"],"a":1},{"q":"¿Qué pide Mamet (1991) con «entrar tarde, salir temprano»?","o":["a) Llegar tarde al rodaje","b) Empezar la escena en el último momento posible y cortarla en el primero después de lo decidido","c) Filmar solo de noche","d) No usar diálogo"],"a":1},{"q":"¿Qué defiende Bazin (1958-1962) frente al montaje?","o":["a) Los quince golpes","b) El objetivo del actor","c) El plano secuencia y la profundidad de campo","d) La escena francesa"],"a":2},{"q":"¿Sobre qué habla en realidad «nadie sabe nada» de Goldman (1983)?","o":["a) Sobre la taquilla, no sobre cómo se escribe una escena","b) Sobre el subtexto","c) Sobre el plano secuencia","d) Sobre el objetivo del actor"],"a":0},{"q":"¿Qué es la escena francesa?","o":["a) Una medición con corpus","b) Una convención teatral marcada por entradas y salidas, sin autor único","c) Una plantilla comercial de Hollywood","d) El sistema de Stanislavski"],"a":1},{"q":"¿Qué tres cosas pide la cuenta de la escena de esta etapa?","o":["a) Título, fecha y lugar","b) Presupuesto, elenco y locación","c) Género, tono y duración","d) Valor al entrar, valor al salir y qué lo movió"],"a":3},{"q":"¿Qué le pasó a «La Gaviota» de Chéjov en 1896 y en 1898?","o":["a) Fracasó en 1896 y triunfó en 1898 con Stanislavski","b) Triunfó las dos veces","c) Nunca se estrenó","d) Ganó un premio en 1896"],"a":0},{"q":"¿Qué es un beat, para McKee (1997)?","o":["a) Un acto completo","b) Un intercambio de acción y reacción dentro de la escena","c) Una plantilla comercial","d) Un tipo de plano secuencia"],"a":1},{"q":"¿Qué es el «si mágico» de Stanislavski?","o":["a) Una pregunta que convierte una circunstancia inventada en un impulso real de actuar","b) Un truco de montaje","c) Una plantilla de guion","d) Una medición de corpus"],"a":0},{"q":"¿Qué le objeta Bazin al montaje, en el fondo?","o":["a) Que es demasiado caro","b) Que necesita demasiados actores","c) Que le impone al espectador dónde tiene que mirar, en vez de dejarlo elegir","d) Que no sirve para el teatro"],"a":2},{"q":"¿Qué le pasó al sistema de Stanislavski a lo largo de su vida?","o":["a) Se quedó exactamente igual desde 1898","b) Lo abandonó por completo","c) Nunca lo escribió","d) El propio Stanislavski lo revisó, moviéndose hacia el método de las acciones físicas"],"a":3},{"q":"¿Qué etiqueta le corresponde a «On Directing Film» de Mamet (1991)?","o":["a) Medición con corpus","b) Forma tradicional sin autor único","c) Postura de oficio, declarada y polémica","d) Clásico fundacional del teatro"],"a":2}];
