// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"s. XVII","icon":"🎭","label":"La escena francesa","text":"En el teatro clásico francés se fija la costumbre de marcar una <strong>escena</strong> nueva cada vez que un personaje entra o sale del escenario. <strong>Por qué importa aquí:</strong> es la pieza más vieja de esta etapa, y la única sin autor al que fecharla: se declara <strong>forma tradicional, sin autor único</strong>, y esa es su etiqueta correcta."},{"y":"1896 · 1898","icon":"🕊️","label":"La Gaviota: fracaso y triunfo","text":"Antón Chéjov estrena <strong>«La Gaviota»</strong> en 1896 en el Alexandrinski de San Petersburgo, y fracasa tan estrepitosamente que jura no volver a escribir teatro; en 1898 el recién fundado <strong>Teatro de Arte de Moscú</strong>, dirigida por Konstantin Stanislavski, la repone y triunfa: la gaviota es desde entonces su emblema. <strong>Por qué importa aquí:</strong> es el caso real de un giro completo de valor, del fracaso al triunfo, movido por un método de dirección centrado en el objetivo y el subtexto."},{"y":"1936","icon":"🎯","label":"Stanislavski publica su sistema","text":"Se publica en inglés, como <strong>«An Actor Prepares»</strong>, la obra donde Konstantin Stanislavski describe el objetivo, las unidades de la escena, el subtexto y el si mágico. <strong>Por qué importa aquí:</strong> es la fuente del sistema que esta etapa usa para mirar la escena desde dentro del personaje."},{"y":"1958-1962","icon":"🎥","label":"Bazin y el plano secuencia","text":"Se publica, tras la muerte de André Bazin en 1958, <strong>«¿Qué es el cine?»</strong> (Qu'est-ce que le cinéma?), con su defensa del plano secuencia y la profundidad de campo frente al montaje. <strong>Por qué importa aquí:</strong> es la objeción real que esta etapa enfrenta a la máxima de Mamet en su careo."},{"y":"1983","icon":"✍️","label":"Goldman y el negocio","text":"William Goldman publica <strong>«Adventures in the Screen Trade»</strong>, sus memorias de guionista, con la frase «nadie sabe nada». <strong>Por qué importa aquí:</strong> es la cita más citada fuera de su sentido real de toda la etapa, y esta etapa enseña a devolverla a su lugar: habla del negocio, no del oficio."},{"y":"1991","icon":"✂️","label":"Mamet y el corte","text":"David Mamet publica <strong>«On Directing Film»</strong>, con su máxima «entrar tarde, salir temprano» y su defensa del corte como herramienta de significado. <strong>Por qué importa aquí:</strong> es la postura de oficio, declarada y polémica, que sostiene media etapa y todo su careo."},{"y":"1997","icon":"⚖️","label":"McKee y el giro de valor","text":"Robert McKee publica <strong>«Story»</strong>, con la escena como unidad mínima de trabajo de un relato: gira una carga de valor de un signo al contrario, o es un no-acontecimiento. <strong>Por qué importa aquí:</strong> es la herramienta central de toda la etapa, la que da nombre a su título."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ============ SIMULACIÓN: LA ESCENA QUE «SE VE REAL» ============
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(cortaYDeclara){sfx(cortaYDeclara?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(cortaYDeclara){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">✂️</span><span class="ms-text"><strong>Cortaste hasta el beat:</strong> la escena quedó en cuarenta y cinco segundos, con los últimos cinco de margen para que se sintiera el peso de la frase. Nadie extrañó los tres minutos de saludos.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📋</span><span class="ms-text"><strong>Quedó apuntada la razón del corte:</strong> «entra tarde, sale temprano, Mamet 1991», para que la próxima vez no haga falta discutirlo desde cero.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">📼</span><span class="ms-text"><strong>Dejaste los cuatro minutos completos:</strong> el video de siete minutos que tenía que caber en dos escenas se quedó con espacio para una sola, y hubo que sacar otra escena entera para que cupiera el resto.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🎬</span><span class="ms-text"><strong>Confundir «se ve real» con «dura lo mismo que en la vida»</strong> es exactamente el error que Mamet (1991) señala: lo real de una escena no es su duración, es que el público sienta el giro. Cortar no miente; deja ver mejor lo que de verdad importa.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
// Las llaves del laboratorio (esperado, paradoja, utilidad, ruina) se HEREDAN
// del molde a propósito: los botones del HTML llaman labShowParte('esperado')
// etc., y renombrarlas aquí sin tocar ese archivo rompería el laboratorio en
// silencio. El nombre visible sale de cada «nombre», nunca de la llave. En
// esta etapa el reparto es: esperado = el giro de valor (McKee), paradoja =
// el objetivo y el conflicto (Stanislavski), utilidad = el subtexto
// (Stanislavski), ruina = entrar tarde, salir temprano (Mamet).
const parteData={"esperado":{"nombre":"El giro de valor","icon":"⚖️","estructura":{"title":"Qué es","info":"• <strong>Robert McKee, «Story» (1997)</strong>: la escena es la unidad mínima de trabajo de un relato, y tiene que girar una carga de valor (poder, verdad, vida, confianza) de un signo al signo contrario<br>• Si el signo de entrada es el mismo que el de salida, McKee lo llama <strong>no-acontecimiento</strong>: una escena que se puede borrar sin que la historia se entere<br>• Dentro de la escena, el giro se mueve por <strong>beats</strong>: intercambios de acción y reacción entre los personajes<br>• Es la herramienta que da nombre a esta etapa entera"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿en qué valor y con qué signo entra la escena?<br>• Se pregunta: ¿en qué valor y con qué signo sale?<br>• Si las dos respuestas son iguales, no hay escena todavía, hay un trámite<br>• Se busca el beat concreto (la acción o revelación) que movió el signo de uno al otro"},"enfermedades":{"title":"Dónde se cae","info":"• En escribir una escena con diálogo y duración, pero sin decidir su signo de entrada ni de salida<br>• En dar por hecho el giro sin nombrar qué lo movió<br>• En confundir movimiento (que algo pase) con giro (que algo cambie de signo)<br>• En citar «Story» sin su año, como si fuera una ley de siempre"},"cuidados":{"title":"En esta casa","info":"• Toda escena que se escribe o se filma pasa por la cuenta de la escena antes de darse por buena<br>• Se declara siempre «McKee, 1997» al lado, no «así se escribe una escena»<br>• Se usa como diagnóstico de un borrador: las escenas sin giro son las primeras que se revisan<br>• Y se recuerda que el giro no necesita un villano: puede moverlo una revelación o una decisión"}},"paradoja":{"nombre":"El objetivo y el conflicto","icon":"🎯","estructura":{"title":"Qué es","info":"• <strong>Konstantin Stanislavski, «El trabajo del actor sobre sí mismo» (1936)</strong>: cada personaje entra a la escena queriendo algo concreto y activo, su objetivo<br>• Cuando dos objetivos chocan dentro de la misma escena, aparece el conflicto que la mueve<br>• El si mágico («¿qué haría yo si esto me pasara de verdad?») es la pregunta que convierte una circunstancia inventada en un impulso real de actuar<br>• Es un sistema pensado desde el actor, para el escenario, no un manual de guion"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿qué quiere conseguir cada personaje, en esta escena, ahora mismo?<br>• Se comprueba que el objetivo sea concreto (algo que se puede lograr o no) y no un sentimiento suelto<br>• Se busca el objetivo del otro personaje, y se comprueba si de verdad chocan<br>• Se aplica el si mágico cuando el objetivo se siente forzado o de cartón"},"enfermedades":{"title":"Dónde se cae","info":"• En darle al actor una emoción para actuar en vez de un objetivo para perseguir<br>• En escribir dos personajes que quieren lo mismo, sin ningún choque real<br>• En vender el sistema de Stanislavski como ciencia comprobada, cuando es un método de oficio de teatro<br>• En olvidar que el propio Stanislavski revisó su sistema a lo largo de su vida"},"cuidados":{"title":"En esta casa","info":"• Antes de grabar una escena real, se escribe en una línea el objetivo de cada quien<br>• Se declara «Stanislavski, 1936» al lado, no «así actúan los buenos actores»<br>• Se usa el si mágico con los voluntarios que actúan en los videos, para que el impulso sea real<br>• Y se recuerda que el sistema es para el escenario: al guion le sirve como diagnóstico, no como receta literal"}},"utilidad":{"nombre":"El subtexto","icon":"🗣️","estructura":{"title":"Qué es","info":"• Del mismo sistema de <strong>Stanislavski (1936)</strong>: lo que un personaje dice en voz alta casi nunca es lo que de verdad quiere<br>• El subtexto es esa corriente de deseo que corre por debajo del diálogo<br>• Un personaje puede decir «no hay prisa» y en el subtexto estar pidiendo que se apuren<br>• Es lo que el actor tiene que sostener por dentro, y lo que quien escribe tiene que dejar sentir sin decirlo"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿qué dice este personaje, línea por línea?<br>• Se pregunta, por separado: ¿qué quiere de verdad, en esa misma línea?<br>• Si las dos respuestas son idénticas, la escena «explica» en vez de actuar (la crítica de Mamet, 1991)<br>• Se comprueba leyendo el diálogo en voz alta, escuchando dónde suena hueco"},"enfermedades":{"title":"Dónde se cae","info":"• En escribir diálogo donde los personajes dicen exactamente lo que sienten, sin ningún filtro<br>• En confundir el subtexto con un secreto que se revela después: el subtexto está presente todo el tiempo, aunque no se diga<br>• En que un actor actúe la palabra en vez del deseo de debajo<br>• En olvidar que el subtexto no sustituye al objetivo: lo acompaña"},"cuidados":{"title":"En esta casa","info":"• En cada escena real que se filma, se escribe aparte lo que el diálogo dice y lo que el personaje quiere de verdad<br>• Se declara el sistema de Stanislavski (1936) cuando se enseña esta pieza, no «así actúa la gente»<br>• Se usa el subtexto para revisar diálogo que suena a explicación: si dice justo lo que quiere decir, se reescribe<br>• Y se recuerda que el subtexto sin objetivo detrás es solo un truco vacío"}},"ruina":{"nombre":"Entrar tarde, salir temprano","icon":"✂️","estructura":{"title":"Qué es","info":"• <strong>David Mamet, «On Directing Film» (1991)</strong>: la escena no empieza cuando alguien llega ni termina cuando se va<br>• Empieza en el último momento posible antes de que algo tenga que decidirse<br>• Termina en el primer momento posible después de que ya se decidió<br>• Es una postura de oficio, declarada y polémica por el propio Mamet, no un hallazgo medido"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿qué pasa antes del primer momento importante? Si no mueve nada, se corta<br>• Se pregunta: ¿qué pasa después del último momento importante? Si no mueve nada, se corta<br>• Se compara la escena cortada con la completa: ¿se perdió algún giro de valor, o solo trámite?<br>• Se enfrenta, cuando aplica, con la objeción de Bazin (1958-1962): a veces cortar quita más de lo que ordena"},"enfermedades":{"title":"Dónde se cae","info":"• En dejar saludos, despedidas y explicaciones de contexto que no mueven ningún valor<br>• En aplicar el corte como regla ciega, sin preguntar si esta escena necesitaba respirar<br>• En vender la máxima de Mamet como la única manera correcta de tallar una escena<br>• En cortar tanto que se pierde el beat que de verdad hacía girar el valor"},"cuidados":{"title":"En esta casa","info":"• Todo guion de video de la casa se revisa preguntando dónde entra tarde y dónde sale temprano de verdad<br>• Se declara «Mamet, 1991» al lado, y se reconoce la disputa con Bazin cuando aplica<br>• Se prueba leyendo la escena completa primero, y después la cortada, para comparar qué se perdió<br>• Y se recuerda que el corte es una herramienta de significado, no un ahorro de tiempo de rodaje"}}};
let labParte='esperado',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`⚙️ Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

/* Las tres baterías de pantalla las monta ahora js/lecturas.js dentro de
   cada lectura, leyendo estos mismos bancos por su etiqueta de voz. */

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso. Con las dos
// entrevistas la etiqueta crece: además del pastiche hay que declarar que el
// encuentro nunca ocurrió, porque una hoja suelta se fotocopia y viaja sola,
// y una entrevista apócrifa sin declarar es un parte falso con buena cara.
const LECTURAS_IMPR={"borges":{"titulo":"El instante que nadie vio girar","tipo":"Cuento, a la manera de Jorge Luis Borges"},"cervantes":{"titulo":"Donde se cuenta cómo en una venta la esperanza se volvió ruina, y la ruina, esperanza otra vez, sin que nadie se levantara de la mesa","tipo":"Capítulo, a la manera de Miguel de Cervantes Saavedra"},"harari":{"titulo":"La especie que recuerda por escenas","tipo":"Ensayo, a la manera de Yuval Noah Harari"},"entrevista":{"titulo":"El sistema que nunca dejó de cambiar","tipo":"Entrevista imaginada con Konstantin Stanislavski, a la manera de Joaquín Soler Serrano","ficcion":true},"gala":{"titulo":"El segundo en que cambia el color de la tarde","tipo":"El Loco de la Colina: Jesús Quintero conversa con Antonio Gala (conversación imaginada)","ficcion":true},"debate":{"titulo":"¿La escena se talla cortando, o se deja respirar? Mamet contra Bazin","tipo":"Careo: las dos posturas de una disputa abierta, con sus réplicas","careo":true}};
function _etiquetaImpresa(meta){
  if(meta&&meta.careo){
    return '<div class="etiqueta"><strong>⚖️ Careo escrito por la casa sobre una disputa real.</strong> Los turnos los firman los <strong>papeles</strong> (moderación, defensa, objeción) y no personas: aquí no se le pone a nadie una palabra en la boca. Los investigadores se citan en tercera persona como fuentes, <strong>toda obra, revista, fecha y cifra es real y comprobable</strong>, y cada postura va escrita en su mejor versión, no en la que sería fácil de tumbar.</div>';
  }
  if(meta&&meta.ficcion){
    return '<div class="etiqueta"><strong>⚠️ Entrevista imaginada: ejercicio de estilo de la casa, en homenaje.</strong> El encuentro <strong>nunca ocurrió</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando las voces. Las personas son reales, <strong>toda obra, fecha y cifra citada es real y comprobable</strong>, y lo único inventado es la conversación.</div>';
  }
  return '<div class="etiqueta"><strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.</div>';
}
