const lectAnalisisBank=[
{"q":"¿Por qué Ozuna no puede encontrar el instante exacto del giro, aunque ha reconstruido la escena miles de veces? Relaciónalo con la idea del beat de McKee.","guia":"Se espera que el lector conecte la obsesión de Ozuna con la idea de McKee (1997) de que el giro ocurre en un beat, un intercambio mínimo y localizable de acción y reacción. El cuento sugiere que aunque el giro exista de verdad, encontrarlo exige mirar la escena con el mismo cuidado con que se busca una palabra exacta, y que la sensación de «no saber qué pasó» no significa que no haya pasado nada, sino que todavía no se ha hecho la pregunta correcta: en qué signo se entró y en qué signo se salió.","t":"Borges"},
{"q":"El cuento sugiere que la memoria a veces «esconde la bisagra» de una escena. ¿Qué relación ves entre esto y por qué esta etapa insiste en escribir siempre qué movió el giro, y no solo afirmar que hubo un giro?","guia":"Se espera que el lector reconozca que afirmar «algo cambió» sin nombrar el beat concreto es quedarse a medio camino, tanto en la ficción de Ozuna como en el trabajo real de esta etapa: la cuenta de la escena exige la tercera casilla, qué lo movió, precisamente porque una escena sin su causa nombrada es indistinguible de una afirmación sin comprobar. El cuento convierte esa exigencia técnica en una obsesión humana, para que se sienta como una necesidad y no solo como una regla.","t":"Borges"},
{"q":"Identifica los dos giros de valor que ocurren en el capítulo (de la esperanza a la ruina, y de la ruina de vuelta a algo mejor). ¿Qué acción concreta mueve cada uno?","guia":"Se espera que el lector marque el primer giro (de la esperanza inicial a la ruina) movido por la llegada de don Fadrique con solo treinta reales de los trescientos prometidos, y el segundo giro (de la ruina de vuelta a una aceptación razonable) movido por el refrán y el razonamiento de Cebrián, que le recuerda a su amo que treinta reales en mano valen más que trescientos prometidos y no cobrados. Los dos giros tienen una causa nombrable, que es justo lo que la cuenta de la escena de esta etapa pide siempre.","t":"Cervantes"},
{"q":"¿Qué papel cumple Cebrián en la escena? Relaciona su función con lo que esta etapa llama el objetivo de un personaje dentro de una escena.","guia":"Se espera que el lector note que Cebrián, a diferencia de su amo, entra a la escena con un objetivo claro (evitar que Ballesteros se arruine de tristeza antes de contar bien lo que sí tiene), mientras que Ballesteros entra sin ningún objetivo activo, solo con una expectativa pasiva. El personaje que mueve la escena, en este capítulo, no es el que más habla al principio, sino el que tiene algo concreto que conseguir, que es exactamente lo que Stanislavski (1936) llama el objetivo.","t":"Cervantes"},
{"q":"Explica, con tus palabras, qué es la regla del pico y el final de Kahneman, y por qué el ensayo la relaciona con el oficio de contar historias por escenas.","guia":"Se espera que el lector explique que la regla del pico y el final (Kahneman, Fredrickson, Schreiber y Redelmeier, 1993) dice que no recordamos el promedio de una experiencia, sino su momento más intenso y cómo terminó, y que el ensayo la relaciona con el oficio de contar historias porque una escena bien construida hace exactamente eso: concentra el peso en un momento (el beat) y en un final (el giro), en vez de repartir la atención por igual en todos los instantes, que es como de todas formas la memoria humana ya funciona.","t":"Harari"},
{"q":"¿Qué peligro señala el ensayo al final, sobre la facilidad con que la mente humana cree en un giro de valor? Da un ejemplo propio, distinto de los que trae el texto.","guia":"Se espera que el lector identifique el peligro de que, si la mente recuerda por escenas y por giros, también se le puede vender un giro falso con la misma facilidad con que recuerda uno verdadero, y que la defensa que propone el ensayo es exigir siempre el dato concreto que movió el cambio. El ejemplo propio puede ser cualquier caso donde alguien afirme que «algo cambió por completo» sin nombrar la acción o el dato que lo causó, dentro o fuera del propio proyecto.","t":"Harari"},
{"q":"¿Por qué esta entrevista se declara imposible? Explica con las fechas exactas por qué el encuentro nunca pudo ocurrir.","guia":"Se espera que el lector calcule que Konstantin Stanislavski murió en 1938, y que el programa «A fondo» de Joaquín Soler Serrano se emitió entre 1976 y 1981 en Televisión Española, casi cuarenta años después: el encuentro es materialmente imposible, y por eso la pieza se declara como entrevista imposible, un género donde la casa presta la voz a alguien que ya no puede hablar, dejando claro que las palabras son invención mientras que la biografía, las obras y las fechas de la persona real son comprobables.","t":"Entrevista"},
{"q":"En la entrevista, Stanislavski corrige a sus propios discípulos sobre la memoria emotiva. ¿Qué dice que aprendió, y por qué esta etapa incluye esa corrección en vez de presentar su sistema como una idea cerrada desde el principio?","guia":"Se espera que el lector explique que Stanislavski, según la entrevista, dejó de apoyarse tanto en la memoria emotiva (revivir un dolor propio para prestárselo al personaje) y se movió, en sus últimos años, hacia el método de las acciones físicas, confiando en que la emoción aparece sola si el cuerpo persigue de verdad el objetivo. La etapa incluye esta corrección porque su propia regla de oro exige tratar cada sistema como una herramienta con fecha, que puede revisarse, y no como una ley cerrada de una vez para siempre, ni siquiera cuando la revisión la hace el mismo autor.","t":"Entrevista"},
{"q":"¿Qué quiere decir Gala cuando afirma que en la escena de Jimena «cambia de color toda la tarde»? Relaciónalo con el giro de valor de McKee.","guia":"Se espera que el lector conecte la imagen de Gala («cambia de color toda la tarde») con el giro de valor de McKee: Jimena entra a la escena siendo, ante todo, la viuda del Cid, y sale siendo, por primera vez, ella misma, una persona con una pregunta propia por delante. El cambio de color es una manera poética de nombrar exactamente lo que esta etapa llama el cambio de signo entre el valor de entrada y el valor de salida de una escena.","t":"Quintero y Gala"},
{"q":"Gala dice que «se busca a propósito, y casi siempre se encuentra por accidente». ¿A qué se refiere, y qué relación tiene con la idea de que el personaje, no el autor, decide el giro?","guia":"Se espera que el lector entienda que Gala describe el trabajo de escribir como una búsqueda dirigida (se sabe que algo tiene que cambiar) que rara vez llega por el camino planeado: el instante exacto suele aparecer cuando el personaje, dentro de la lógica de la escena, responde de una manera que el autor no había calculado del todo. Esto se relaciona con que el giro de una escena real, en el trabajo de esta casa, tampoco se puede forzar desde fuera: hay que dejar que el objetivo y el conflicto de cada quien lo produzcan.","t":"Quintero y Gala"},
{"q":"Explica la disputa central del careo entre Mamet y Bazin, y por qué la moderación dice que el terreno común es más grande de lo que parece.","guia":"Se espera que el lector explique que Mamet (1991) defiende cortar la escena en el instante exacto del giro, mientras que Bazin (1958-1962) defiende dejarla respirar en plano secuencia y profundidad de campo, y que la disputa real es sobre dónde va el corte y qué se pierde al ponerlo, no sobre si la escena debe girar en un valor, que las dos partes aceptan. El terreno común es más grande de lo esperado porque ambas posturas coinciden en que la técnica elegida tiene siempre un costo, y que ninguna de las dos es una ley universal sin excepciones.","t":"Debate"},
{"q":"¿Qué dato concreto propone el careo para acercar la disputa entre cortar y no cortar? ¿Por qué ese dato, y no otro, la resolvería mejor?","guia":"Se espera que el lector identifique que el careo propone una comparación, con público real, de cómo se recuerda una misma escena contada cortada frente a la misma escena contada en plano secuencia, y que explique por qué ese dato (y no una opinión de crítico o director) resolvería mejor la disputa: porque mediría el efecto real sobre quien recibe la historia, que es justo lo que las dos posturas dicen defender, en vez de quedarse en el terreno de la preferencia estética de cada autor.","t":"Debate"}
];

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue buscando el valor de entrada y de salida de cada escena!','¡Muy buen trabajo!','¡Ya distingues el objetivo del subtexto!','¡Ya sabes cuándo cortar y cuándo dejar respirar!','¡Ninguna escena se te escapa sin su giro!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🎭 ¡'+name+' completó la Etapa 4 de la Ruta del Hilo que Tira (La escena)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

